import{_ as o,o as a,c as t,a3 as l}from"./chunks/framework.DACwFHq9.js";const p=JSON.parse('{"title":"Knowledge 在当前管道中的位置","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/tools/llm-chat/context-pipeline/knowledge-processor.md","filePath":"user-guide/tools/llm-chat/context-pipeline/knowledge-processor.md","lastUpdated":1784437941000}'),n={name:"user-guide/tools/llm-chat/context-pipeline/knowledge-processor.md"};function r(d,e,i,s,c,g){return a(),t("div",null,[...e[0]||(e[0]=[l('<div><h1 id="knowledge-在当前管道中的位置" tabindex="-1">Knowledge 在当前管道中的位置 <a class="header-anchor" href="#knowledge-在当前管道中的位置" aria-label="Permalink to &quot;Knowledge 在当前管道中的位置&quot;">​</a></h1><p>Knowledge 没有独立的上下文管道处理器，也不会因为 Agent 获得资料库权限而自动执行 RAG。它是一个按需调用的工具领域：Agent 主动调用 <code>knowledge.listLibraries</code>、<code>knowledge.search</code>、<code>knowledge.read</code>，或用户在聊天输入区显式引用资料库时，系统才执行检索。</p><h2 id="_1-工作原理" tabindex="-1">1. 工作原理 <a class="header-anchor" href="#_1-工作原理" aria-label="Permalink to &quot;1. 工作原理&quot;">​</a></h2><ol><li><strong>授权</strong>：从当前 Agent 快照读取 <code>knowledgeAccess</code>，校验资料库 ID 和能力权限。</li><li><strong>检索</strong>：通过 Knowledge application service 调用 <code>listLibraries</code>、<code>search</code> 或 <code>read</code>，不复制另一套权限逻辑。</li><li><strong>证据回传</strong>：工具事件保留资料库、文档、chunk、来源路径、实际策略和失败原因。</li><li><strong>回答编排</strong>：快速查询或研究任务的结构化结果交回当前 Agent，由当前 Agent 决定如何回答。</li></ol><h2 id="_2-agent-级权限" tabindex="-1">2. Agent 级权限 <a class="header-anchor" href="#_2-agent-级权限" aria-label="Permalink to &quot;2. Agent 级权限&quot;">​</a></h2><p>在 Agent 编辑器的 <strong>「知识库 (Knowledge) -&gt; Knowledge 资料访问权限」</strong> 面板中编辑 <code>knowledgeAccess</code>：是否启用、允许的资料库、是否允许省略资料库范围、是否允许继续读取文档，以及是否允许研究任务。检索策略、预算和过滤条件属于单次工具调用参数，不会写入 Agent 的资料库授权。</p><h2 id="_3-调试与分析" tabindex="-1">3. 调试与分析 <a class="header-anchor" href="#_3-调试与分析" aria-label="Permalink to &quot;3. 调试与分析&quot;">​</a></h2><p>如果你觉得 AI “胡言乱语”或没有引用知识库内容：</p><ol><li>查看聊天中的 Knowledge 工具节点和引用列表。</li><li>检查工具结果中的资料库 ID、文档、chunk、来源路径和实际检索策略。</li><li>研究任务还会显示轮次、证据预算、空缺、冲突和终止原因。</li></ol><hr><h3 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h3><ul><li><a href="./../../knowledge-base">知识库管理工具指南</a></li><li><a href="./../agents/parameters">Agent 参数配置</a></li><li><a href="./../../knowledge-base/agent-integration">Knowledge Agent 集成</a></li></ul></div>',1)])])}const _=o(n,[["render",r]]);export{p as __pageData,_ as default};
